import {carSvg} from './lt32-car.mjs?v=1.1.0';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function equipmentPhoto(s){return `<svg viewBox="0 0 680 430" class="equipment-photo" role="img" aria-label="Foto do LT-32 PRO enviada pelo técnico. IMEI ${s.imei.split('').join(' ')}. Há também número de série e ICCID."><defs><linearGradient id="bench" x2="1" y2="1"><stop stop-color="#58635a"/><stop offset="1" stop-color="#273c3e"/></linearGradient></defs><rect width="680" height="430" fill="url(#bench)"/><path d="M0 370 680 267M0 180 680 77" stroke="#879082" stroke-width="2" opacity=".2"/><text x="27" y="33" fill="#d5dbbc" font-family="system-ui" font-size="12" letter-spacing="2">ANDERSON / FOTO DO EQUIPAMENTO</text><g transform="translate(74 69) rotate(-3 270 150)"><ellipse cx="277" cy="273" rx="269" ry="36" fill="#071219" opacity=".4"/><rect x="14" y="23" width="520" height="280" rx="29" fill="#17262c" stroke="#0a151a" stroke-width="9"/><path d="M534 73h29v146h-29" fill="#112026"/><path d="M563 92h42m-42 23h42m-42 23h42m-42 23h42" stroke="#cdb794" stroke-width="9"/><rect x="47" y="56" width="447" height="216" rx="6" fill="#e8e3ce" stroke="#afb3a1" stroke-width="3"/><text x="68" y="88" font-size="19" font-family="system-ui" fill="#2a3738" font-weight="800">LUMINI TRACKER / LT32 PRO</text><text x="68" y="116" font-family="system-ui" font-size="12" fill="#666f61">IMEI · EQUIPAMENTO</text><text x="68" y="151" font-family="monospace" font-size="29" fill="#172e31" font-weight="700">${s.imei}</text><path d="M70 164v24m5-24v24m9-24v24m4-24v24m9-24v24m7-24v24m4-24v24m8-24v24m11-24v24m5-24v24m9-24v24m5-24v24m9-24v24m5-24v24m9-24v24m5-24v24m9-24v24m10-24v24m5-24v24m8-24v24m5-24v24m9-24v24m5-24v24m9-24v24m5-24v24m11-24v24m5-24v24m8-24v24m5-24v24m9-24v24" stroke="#273538" stroke-width="3"/><text x="68" y="213" font-size="13" font-family="monospace" fill="#455650">S/N: ${s.serial}</text><text x="68" y="242" font-size="13" font-family="monospace" fill="#455650">ICCID: ${s.iccid}</text><circle cx="60" cy="286" r="5" fill="#ef7658"/><circle cx="81" cy="286" r="5" fill="#efcc5c"/><circle cx="102" cy="286" r="5" fill="#77b3bd"/></g><text x="28" y="406" fill="#d6d9bf" font-family="system-ui" font-size="12">LT-32 PRO · ORDEM DE INSTALAÇÃO / SIMULAÇÃO</text></svg>`;}
export function installationPhoto(s){return `<div class="installation-photo">${carSvg({phase:'hiding',location:s.installationLocation,hidden:true,openParts:['trim','hood','door','trunk']},{interactive:false})}<span class="photo-pin" style="left:${s.installationLocation==='rear-trim'?61:77}%;top:65%">LT-32 PRO</span></div>`;}
const route=[[138,338],[266,338],[266,235],[414,235],[414,128],[585,128],[585,235],[722,235],[722,338],[585,338],[585,446],[414,446],[266,446],[138,446],[138,338]];
export function vehiclePoint(ms){const fraction=(ms%60000)/60000*(route.length-1),i=Math.floor(fraction),t=fraction-i,a=route[i],b=route[i+1];return {x:a[0]+(b[0]-a[0])*t,y:a[1]+(b[1]-a[1])*t,angle:Math.atan2(b[1]-a[1],b[0]-a[0])*180/Math.PI};}
export function mapSvg(s){const ready=s.gpsReady,p=vehiclePoint(s.phase==='finish'?s.finishMs:0);return `<svg class="tracking-map" viewBox="0 0 860 560" role="img" aria-label="Mapa fictício de rastreamento. ${s.phase==='finish'?'O veículo se move automaticamente.':ready?'Rastreador posicionado em verde.':'Aguardando primeira posição.'}"><rect width="860" height="560" fill="#1c3035"/><g fill="#2b4446" stroke="#365253" stroke-width="2">${[65,180,290,405].map((y,j)=>[40,175,315,465,635,775].map((x,i)=>`<rect x="${x}" y="${y}" width="${i===5?57:83}" height="${j===3?99:73}" rx="5"/>`).join('')).join('')}</g><path d="M30 520C190 450 70 330 185 270S690 195 830 35" fill="none" stroke="#315c65" stroke-width="40" opacity=".6"/><rect x="616" y="375" width="95" height="128" rx="15" fill="#405b42"/><g fill="#54704c"><circle cx="637" cy="397" r="10"/><circle cx="683" cy="425" r="13"/><circle cx="646" cy="465" r="16"/></g><g stroke="#637376" stroke-width="19" fill="none"><path d="M0 128H860M0 235H860M0 338H860M0 446H860M138 0V560M266 0V560M414 0V560M585 0V560M722 0V560"/></g><g stroke="#d4c499" stroke-width="1" stroke-dasharray="7 9" opacity=".35"><path d="M0 128H860M0 235H860M0 338H860M0 446H860M138 0V560M266 0V560M414 0V560M585 0V560M722 0V560"/></g><text x="330" y="322" font-family="system-ui" font-size="11" fill="#b4c1ad" letter-spacing="2">AV. DOS ANDERSONS</text><text x="635" y="545" font-family="system-ui" font-size="10" fill="#a6b49f">CENÁRIO FICTÍCIO</text>${s.phase==='finish'?`<polyline points="${route.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#b3cd8b" stroke-width="4" opacity=".6" stroke-dasharray="5 10"/>`:''}<g id="moving-vehicle" transform="translate(${p.x} ${p.y}) rotate(${p.angle})"><circle class="gps-ring ${ready?'ready':''}" r="34" fill="${ready?'#b4db8920':'#8c9c9e20'}" stroke="${ready?'#afcc84':'#849a9d'}" stroke-width="2"/><rect x="-20" y="-10" width="40" height="20" rx="8" fill="${ready?'#eeb15f':'#8a9999'}" stroke="#15292c" stroke-width="3"/><path d="M-4-8h13l5 6V3l-5 6H-4Z" fill="#304c54"/><rect x="-14" y="-6" width="7" height="12" rx="1" fill="#d7c099"/></g></svg>`;}
export const phaseName=s=>({imei:'Identificar aparelho',maze:'Testes e cadastro',platform:'Primeira posição',location:'Enviar localização',handoff:'Liberar acesso',credentials:'Enviar acesso',finish:'Instalação concluída',failed:'Expediente encerrado'}[s.phase]);
